package mtc

import (
	"bytes"
	"crypto/mldsa"
	"crypto/sha256"
	stdx509 "crypto/x509"
	"encoding/base64"
	"encoding/pem"
	"fmt"
	"os"
	"strings"
	"testing"

	"github.com/zmap/zcrypto/x509"
	"github.com/zmap/zlint/v3/lint"
	"github.com/zmap/zlint/v3/test"
)

// testCosignerKey returns the public key of the test cosigner with the given
// ID. mtc_magnolia_cosigned.pem was generated by Magnolia
// (geomys.org/magnolia/internal/mtc) with cosignatures from the cosigners
// 66252.0 and 66252.1, whose ML-DSA-44 seeds are SHA-256("zlint test cosigner
// " || ID).
func testCosignerKey(t *testing.T, id string) string {
	t.Helper()
	seed := sha256.Sum256([]byte("zlint test cosigner " + id))
	key, err := mldsa.NewPrivateKey(mldsa.MLDSA44(), seed[:])
	if err != nil {
		t.Fatal(err)
	}
	spki, err := stdx509.MarshalPKIXPublicKey(key.Public())
	if err != nil {
		t.Fatal(err)
	}
	return base64.StdEncoding.EncodeToString(spki)
}

func readMTCFile(t *testing.T, filename string) []byte {
	t.Helper()
	data, err := os.ReadFile("../../testdata/" + filename)
	if err != nil {
		t.Fatal(err)
	}
	block, _ := pem.Decode(data)
	if block == nil || block.Type != "CERTIFICATE" {
		t.Fatal("failed to decode test certificate")
	}
	return block.Bytes
}

const landmarkHash = "2ac543a47ee717c21d1163f8ccd5356753f9881139571a9378b4562c704e2bb4"

func TestMTCProofVerifies(t *testing.T) {
	mirror := testCosignerKey(t, "66252.0")
	ca := testCosignerKey(t, "66252.1")
	cosigner := func(id, key string, required bool) string {
		return fmt.Sprintf("[[e_mtc_proof_verifies.Cosigners]]\nID = %q\nPublicKey = %q\nRequired = %v\n", id, key, required)
	}
	subtree := func(start, end int, hash string) string {
		return fmt.Sprintf("[[e_mtc_proof_verifies.Subtrees]]\nStart = %d\nEnd = %d\nHash = %q\n", start, end, hash)
	}
	standalone := "[e_mtc_proof_verifies]\nMode = \"standalone\"\n"
	landmark := "[e_mtc_proof_verifies]\nMode = \"landmark\"\n"

	cosigned := readMTCFile(t, "mtc_magnolia_cosigned.pem")
	// Changing a SAN in the TBSCertificate changes the log entry, and so
	// the subtree hash, without making the certificate unparseable.
	tampered := bytes.Replace(cosigned, []byte("example.com"), []byte("examplf.com"), 1)
	if bytes.Equal(tampered, cosigned) {
		t.Fatal("failed to tamper with the certificate")
	}
	landmarkCert := readMTCFile(t, "mtc_magnolia_landmark.pem")

	for _, tt := range []struct {
		name    string
		cert    []byte
		config  string
		want    lint.LintStatus
		details string
	}{
		{"unconfigured", cosigned, "", lint.NA, ""},
		{"unknown mode", cosigned, "[e_mtc_proof_verifies]\nMode = \"foo\"\n", lint.Fatal, "unknown mode"},

		{"standalone", cosigned, standalone +
			cosigner("66252.0", mirror, true) + cosigner("66252.1", ca, true), lint.Pass, ""},
		{"standalone with unconfigured cosigner", cosigned, standalone +
			cosigner("66252.1", ca, true), lint.Pass, ""},
		{"standalone with absent optional cosigner", cosigned, standalone +
			cosigner("66252.1", ca, false) + cosigner("66252.2", ca, false), lint.Pass, ""},
		{"standalone with wrong key", cosigned, standalone +
			cosigner("66252.0", mirror, true) + cosigner("66252.1", mirror, true), lint.Error, "invalid cosignature from cosigner 66252.1"},
		{"standalone tampered", tampered, standalone +
			cosigner("66252.1", ca, true), lint.Error, "invalid cosignature from cosigner 66252.1"},
		{"standalone with absent required cosigner", cosigned, standalone +
			cosigner("66252.1", ca, true) + cosigner("66252.2", ca, true), lint.Error, "missing cosignature from required cosigner 66252.2"},
		{"standalone with no configured cosigner", cosigned, standalone +
			cosigner("66252.2", ca, false), lint.Error, "no cosignature from a configured cosigner"},
		{"standalone with no cosignatures", landmarkCert, standalone +
			cosigner("66252.1", ca, false), lint.Error, "no cosignature from a configured cosigner"},
		{"standalone with invalid key", cosigned, standalone +
			cosigner("66252.1", "AAAA", true), lint.Fatal, "invalid public key"},
		{"standalone with invalid ID", cosigned, standalone +
			cosigner("66252.01", ca, true), lint.Fatal, "invalid trust anchor ID"},

		{"landmark", landmarkCert, landmark +
			subtree(16, 32, strings.Repeat("00", 32)) + subtree(0, 16, landmarkHash), lint.Pass, ""},
		{"landmark with wrong hash", landmarkCert, landmark +
			subtree(0, 16, strings.Repeat("00", 32)), lint.Error, "hash is " + landmarkHash},
		{"landmark with unknown subtree", landmarkCert, landmark +
			subtree(0, 8, landmarkHash), lint.Error, "subtree [0, 16) is not a configured landmark subtree"},
		{"landmark with cosignatures", cosigned, landmark +
			subtree(8, 13, landmarkHash), lint.Error, "landmark-relative certificate has cosignatures"},
		{"landmark with invalid hash", landmarkCert, landmark +
			subtree(0, 16, "00"), lint.Fatal, "invalid hash"},
	} {
		t.Run(tt.name, func(t *testing.T) {
			config, err := lint.NewConfigFromString(tt.config)
			if err != nil {
				t.Fatal(err)
			}
			cert, err := x509.ParseCertificate(tt.cert)
			if err != nil {
				t.Fatal(err)
			}
			result := test.TestLintCert("e_mtc_proof_verifies", cert, config)
			if result.Status != tt.want {
				t.Errorf("got %s (%s), want %s", result.Status, result.Details, tt.want)
			}
			if !strings.Contains(result.Details, tt.details) {
				t.Errorf("details %q do not contain %q", result.Details, tt.details)
			}
		})
	}
}
